import{_ as a}from"./chunks/Fixpipe_Int8_Channel_Merge.CobzoAsV.js";import{_ as t,o as _,a as n,b as r}from"./app.UgfkfLuP.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"Int8 Channel Merge","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/Int8-Channel-Merge"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/Int8-Channel-Merge.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/Int8-Channel-Merge.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1791622466000}'),i={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/Int8-Channel-Merge.md"};function l(s,e,c,o,p,u){return _(),n("div",null,[...e[0]||(e[0]=[r('<div><article class="markdown-body"><h1>Int8 Channel Merge</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中对于目标数据类型被转换为int8_t、uint8_t的情况，Nz输出时该特性自动启用。硬件会将分形矩阵从16×16扩展为16×32。具体规则如下：若输出通道数N是16的偶数倍，则在N方向上，每两个相邻的16×16分形矩阵将合并为一个单一的16×32分形矩阵。若N是16的奇数倍，则通道1至通道（N–16）将被合并，而最后16个通道保持不变，不进行合并。</p><p>该行为与输出数据类型和<a href="NZ2NZ.html">Nz输出布局</a>相关。将float或int32_t结果量化为int8_t/uint8_t时，模式选择和系数配置见<a href="accompanying_quantization.html">随路量化</a>；结果输出到L1的接口见<a href="../cube_compute_store/asc_copy_l0c2l1.html">asc_copy_l0c2l1</a>。分配目的缓冲区和设置步长时，需考虑合并后小分形宽度的变化。</p><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><p>硬件自动开启，不能配置。</p><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>例如，当目标数据类型为s8，M为32，N为48时，硬件会先将N方向上前两个16×16的分形矩阵合并成一个16×32的矩阵，然后将剩余的16×16分形矩阵直接搬运至L1 Buffer。</p><p><strong>图1</strong> Int8 Channel Merge示意图</p><p><img src="'+a+'" alt></p></article></div>',1)])])}const m=t(i,[["render",l]]);export{I as __pageData,m as default};
